INSERT INTO quest_template (title, description, image_url) VALUES
('Goblin Menace', 'A horde of mischievous goblins has invaded the village. Defeat them before they steal all the villagers'' treasures.', 'https://res.cloudinary.com/dfo147x05/image/upload/v1769722981/epic-grafika_kvn97c.png'),
('Dragon''s Lair', 'Rumors speak of a fearsome dragon sleeping atop a mountain of gold. Brave the perilous path and claim the treasure.', 'https://res.cloudinary.com/dfo147x05/image/upload/v1769722981/epic-grafika_kvn97c.png'),
('Cursed Forest', 'The forest has been cursed, and dark creatures roam freely. Venture into the shadows to lift the curse.', 'https://res.cloudinary.com/dfo147x05/image/upload/v1769722981/epic-grafika_kvn97c.png'),
('Bandit Ambush', 'Bandits have set up an ambush along the main road. Fight them off to protect innocent travelers.', 'https://res.cloudinary.com/dfo147x05/image/upload/v1769722981/epic-grafika_kvn97c.png'),
('Mystic Ruins', 'Ancient ruins filled with arcane secrets have been discovered. Explore carefully to uncover hidden artifacts.', 'https://res.cloudinary.com/dfo147x05/image/upload/v1769722981/epic-grafika_kvn97c.png'),
('Haunted Crypt', 'An old crypt has been overrun by restless spirits. Enter if you dare and put their souls to rest.', 'https://res.cloudinary.com/dfo147x05/image/upload/v1769722981/epic-grafika_kvn97c.png'),
('Orc Warlord', 'A mighty orc warlord is terrorizing nearby villages. Defeat him and his minions to restore peace.', 'https://res.cloudinary.com/dfo147x05/image/upload/v1769722981/epic-grafika_kvn97c.png'),
('Enchanted Lake', 'Legends speak of a magical lake guarded by mystical creatures. Retrieve the enchanted pearl.', 'https://res.cloudinary.com/dfo147x05/image/upload/v1769722981/epic-grafika_kvn97c.png'),
('Thieves'' Guild', 'A notorious thieves'' guild has stolen priceless artifacts. Infiltrate their hideout and reclaim the treasures.', 'https://res.cloudinary.com/dfo147x05/image/upload/v1769722981/epic-grafika_kvn97c.png'),
('Vampire Hunt', 'A vampire has been preying on villagers. Track it down and end its reign of terror.', 'https://res.cloudinary.com/dfo147x05/image/upload/v1769722981/epic-grafika_kvn97c.png');